<script setup lang="ts">
import type { HysPopupMotionProps } from '../../motion/popup';

import PopupMotion from '../../motion/PopupMotion';

import {useHysRootAttrs} from '../../config'
const hysRootAttrs=useHysRootAttrs()

import {Command} from 'lucide-vue-next';

import {ref,computed,onMounted,onUnmounted,onActivated,onDeactivated,nextTick,watch,useId} from 'vue';import {useDialog} from '../../composables/useDialog';type Action={id:string;label:string;description?:string};const props=defineProps<HysPopupMotionProps & {actions:Action[]}>();const emit=defineEmits<{ select:[id:string] }>();const resultsId=useId(),open=ref(false),query=ref(''),index=ref(0),input=ref<HTMLInputElement|null>(null),trigger=ref<HTMLButtonElement|null>(null);const dialog=ref<HTMLElement>();const {active,zIndex}=useDialog(open,dialog,close);const filtered=computed(()=>props.actions.filter(x=>(x.label+' '+(x.description||'')).toLowerCase().includes(query.value.toLowerCase())));watch(query,()=>index.value=0);function show(){open.value=true;query.value='';index.value=0;nextTick(()=>input.value?.focus())}function close(){open.value=false}function choose(id:string){emit('select',id);close()}function key(e:KeyboardEvent){if(e.defaultPrevented)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();open.value?close():show()}}function inputKey(e:KeyboardEvent){if(e.isComposing||e.keyCode===229)return;if(e.key==='ArrowDown'){e.preventDefault();index.value=(index.value+1)%Math.max(1,filtered.value.length)}if(e.key==='ArrowUp'){e.preventDefault();index.value=(index.value-1+Math.max(1,filtered.value.length))%Math.max(1,filtered.value.length)}if(e.key==='Enter'&&filtered.value[index.value])choose(filtered.value[index.value].id)}onMounted(()=>window.addEventListener('keydown',key));onActivated(()=>window.addEventListener('keydown',key));onDeactivated(()=>window.removeEventListener('keydown',key));onUnmounted(()=>window.removeEventListener('keydown',key));

</script>
<template><button v-bind="hysRootAttrs" ref="trigger" type="button" class="hys-ui-v4-control" @click="show"><Command :size="14" aria-hidden="true"/> / Ctrl + K · 快捷命令</button><Teleport to="body"><PopupMotion ignore-owner :popup-transition="props.popupTransition" :popup-transition-duration="props.popupTransitionDuration" @inactive="close"><div v-bind="hysRootAttrs" v-if="open&&active" class="hys-ui-v4-backdrop hys-ui-popup-backdrop" :style="{zIndex}" @pointerdown.self="close"><section ref="dialog" tabindex="-1" class="hys-ui-v4-dialog" role="dialog" aria-modal="true" aria-label="快捷命令"><input ref="input" v-model="query" class="hys-ui-v4-control" placeholder="搜索操作…" role="combobox" :aria-controls="resultsId" :aria-expanded="true" @keydown="inputKey"/><div :id="resultsId" role="listbox" class="hys-ui-v4-scroll"><button type="button" v-for="(x,i) in filtered" :key="x.id" class="hys-ui-v4-option" :class="{'hys-ui-v4-active':i===index}" role="option" :aria-selected="i===index" @pointerenter="index=i" @click="choose(x.id)">{{x.label}} <small>{{x.description}}</small></button><p v-if="!filtered.length">没有匹配的命令</p></div><button type="button" class="hys-ui-v4-option" @click="close">关闭 Esc</button></section></div></PopupMotion></Teleport></template>
